const zL = (a, b, c, n = 4) => { const [ux, uy, L] = zdir(a, b), u = [ux, uy], m = L / 2, r = .2; let d = `M${zp(a)} L${zp(zat(a, u, m - n * r))}`; for (let i = 1; i <= n; i++) d += ` A${r} ${r} 0 0 1 ${zp(zat(a, u, m - n * r + 2 * r * i))}`; d += ` L${zp(b)}`; return `<path d="${d}" ${zst(c)}/>`; };
