    code: ['a = [1, 2]', ['b = a                   # 같은 객체에 이름 추가', 'b = a                   # same object'], ['c = [1, 2]              # 값만 같은 새 객체', 'c = [1, 2]              # new, equal object'], 'a == c, a is c          # (True, False)', 'sys.getrefcount(a) - 1  # 2: a, b'],
