function sScope() {
  const BX = [['B', 19.0, .3, 12.4, 6.0, ['Built-in: len, print, range…', 'Built-in: len, print, range…'], 'ink-3'], ['G', 19.4, 1.1, 11.6, 4.9, ['Global (모듈): x = "global"', 'Global (module): x = "global"'], 'accent'], ['E', 19.8, 1.9, 10.8, 3.8, ['Enclosing (outer): x = "enclosing"', 'Enclosing (outer): x = "enclosing"'], 'warn'], ['L', 20.2, 2.7, 10.0, 2.4, ['Local (inner): x 없음', 'Local (inner): no x'], 'ok']];
  return CW('py-scope', {
    code: ['x = "global"', 'def outer():', '    x = "enclosing"', ['    def inner(): return x  # L→E→G→B 순서로', '    def inner(): return x  # L→E→G→B order'], '    return inner', ['fs = [lambda: i for i in range(3)]  # 모두 2', 'fs = [lambda: i for i in range(3)]  # all 2']],
    hl: [[0, 5, 'accent'], [3, 1, 'warn'], [4, 1, 'ok'], [5, 1, 'danger']],
    draw: (S) => {
      BX.forEach(([k, x, y, w, h, t, c]) => { rect(S, 'b' + k, x, y, w, h, c, 10, 1, { r: .25 }); T(S, 'bt' + k, x + .2, y + .12, t, 'cz-mono pyx-tiny', 1, { w: w - .4 }); });
      chip(S, 'look', 21.0, 3.9, 4.6, ['inner의 x?', 'x in inner?'], 'ok', 2, { h: .8 });
      arw(S, 'la', [25.7, 4.3], [27.4, 2.65], 2, { color: 'warn' }); T(S, 'lf', 27.0, 3.35, ['E에서 찾음', 'found in E'], 'cz-tc pyx-tiny pyx-w', 2, { w: 3.6 });
      box2(S, 'cell', 19.0, 6.7, 6.4, .8, 'inner.__closure__ → cell', 'warn', 3); chip(S, 'cv', 25.8, 6.7, 4.4, '"enclosing"', 'warn', 3, { h: .8 }); arw(S, 'ca', [25.45, 7.1], [25.75, 7.1], 3);
      lbl(S, 'l3', 19.0, 7.8, ['outer가 끝나도 셀이 x를 붙잡아 inner가 계속 써요 (클로저)', 'the cell keeps x alive after outer returns, so inner can still use it (a closure)'], 'w', 3, { w: 12.4 });
      [['[f() for f in fs]', '[2, 2, 2]', 'danger'], ['lambda i=i: i', '[0, 1, 2]', 'ok']].forEach(([a, b, c], i) => { T(S, 'fa' + i, 19.0, 9.25 + i * .9, a, 'cz-mono pyx-xs', 4, { w: 6.6 }); chip(S, 'fb' + i, 26.0, 9.1 + i * .9, 4.2, b, c, 4, { h: .8 }); });
      lbl(S, 'm1', 1, 8.1, ['LEGB: Local → Enclosing → Global → Built-in 순서로 이름을 찾아요', 'LEGB: names are looked up Local → Enclosing → Global → Built-in'], 'a', 1, { w: 16.0 });
      lbl(S, 'm3', 1, 9.5, ['바깥 변수에 다시 대입하려면 nonlocal, 모듈 변수는 global', 'rebinding an outer variable needs nonlocal; module variables need global'], '', 3, { w: 16.0 });
      lbl(S, 'm4', 1, 10.9, ['클로저는 값이 아니라 변수를 붙잡아서, 루프가 끝난 뒤의 i = 2를 모두 봐요', 'closures capture variables, not values, so every lambda sees the final i = 2'], 'r', 4, { w: 16.0 });
    },
    notes: [['이름을 찾을 때 파이썬은 지역(Local), 감싸는 함수(Enclosing), 모듈 전역(Global), 내장(Built-in) 순서로 찾아요(LEGB) · 스코프는 함수 단위라 if나 for 블록은 새 스코프를 만들지 않아요', 'Python looks names up in the Local, Enclosing, Global and Built-in scopes in that order (LEGB); scopes are per function, so if and for blocks do not create new ones'], ['inner 안에는 x가 없으니 감싸는 함수 outer에서 "enclosing"을 찾아요 · 함수 안에서 이름에 대입하면 그 이름은 지역 변수가 되고, 바깥 변수에 다시 대입하려면 nonlocal이나 global이 필요해요', 'inner has no x, so it finds "enclosing" in outer; assigning to a name inside a function makes it local, and rebinding an outer variable requires nonlocal or global'], ['outer가 끝나도 inner는 x를 담은 셀(cell)을 붙잡고 있어서 계속 쓸 수 있어요 · 이렇게 바깥 변수를 기억하는 함수가 클로저예요', 'even after outer returns, inner holds the cell containing x and can keep using it; a function that remembers outer variables this way is a closure'], ['클로저는 값이 아니라 변수를 붙잡아요 · 루프에서 만든 람다 세 개는 모두 같은 i를 보고, 호출할 때의 값 2를 돌려줘요 · lambda i=i: i처럼 기본 인자로 그때의 값을 고정해요', 'closures capture variables, not values: the three lambdas made in the loop share one i and all return its value at call time, 2; a default argument such as lambda i=i: i freezes the value']],
    fin: [['LEGB 순서로 이름을 찾고, 대입하면 지역 변수', 'names resolve in LEGB order, and assignment makes a name local', 'pyx-xs pyx-a'], ['클로저는 셀로 바깥 변수를 붙잡아요', 'closures hold outer variables through cells'], ['늦은 바인딩은 기본 인자나 functools.partial로 고정', 'freeze late binding with a default argument or functools.partial']],
    caps: [['LEGB', 'LEGB'], ['이름 찾기', 'Resolving a name'], ['클로저', 'Closures'], ['늦은 바인딩', 'Late binding'], ['스코프와 클로저', 'Scopes and closures']]
  });
}

function sArgs() {
  const PS = [['a', 19.0, 1.1, '1', 'accent'], ['b=2', 20.2, 1.5, '5', 'accent'], ['/', 21.8, .5, '', 'ink-3'], ['c=3', 22.4, 1.5, '6', 'warn'], ['*args', 24.0, 1.9, '(7, 8)', 'ok'], ['d', 26.6, 1.1, '4', 'danger'], ['**kw', 28.9, 2.0, '{"e": 9}', 'ok']];
  const CT = [[['위치만', 'pos-only'], 19.0, 2.7, 'pyx-a'], [['둘 다', 'either'], 22.4, 1.5, 'pyx-w'], [['나머지', 'extra'], 24.0, 1.9, 'pyx-g'], [['키워드만', 'kw-only'], 26.05, 2.2, 'pyx-r'], [['키워드 나머지', 'extra kw'], 28.4, 3.0, 'pyx-g']];
  return CW('py-args', {
    code: ['def f(a, b=2, /, c=3, *args, d, **kw): ...', 'f(1, 5, 6, 7, 8, d=4, e=9)', ['def add(x, acc=[]):        # 기본값은 한 번만', 'def add(x, acc=[]):        # default made once'], '    acc.append(x); return acc', ['add(1); add(2)             # [1, 2] 공유!', 'add(1); add(2)             # [1, 2] shared!']],
    hl: [[0, 1, 'accent'], [1, 1, 'warn'], [2, 3, 'danger'], [2, 1, 'ok']],
    draw: (S) => {
      CT.forEach(([t, x, w, c], i) => T(S, 'ct' + i, x, .2, t, 'cz-tc pyx-tiny ' + c, 1, { w }));
      PS.forEach(([n, x, w, v, c], i) => { chip(S, 'p' + i, x, .9, w, n, c, 1, { h: .9 }); if (v) T(S, 'v' + i, x - .3, 2.05, v, 'cz-mono cz-tc pyx-xs pyx-g', 2, { w: w + .6 }); });
      lbl(S, 'l2', 19.0, 3.0, ['f(1, 5, 6, 7, 8, d=4, e=9): 남는 위치 인자는 args, 모르는 키워드는 kw로', 'leftover positional arguments go to args and unknown keywords to kw'], 'w', 2, { w: 12.4 });
      T(S, 'dh', 19.0, 4.5, 'add.__defaults__', 'cz-mono pyx-xs pyx-r', 3, { w: 5.0 }); chip(S, 'd1', 24.4, 4.35, 2.6, '[1]', 'danger', 3, { h: .8, off: 4 }); chip(S, 'd2', 24.4, 4.35, 2.6, '[1, 2]', 'danger', 4, { h: .8 });
      lbl(S, 'l3', 19.0, 5.6, ['기본값 리스트는 def를 실행할 때 한 번 만들어져 모든 호출이 함께 써요', 'the default list is created once, when def runs, and every call shares it'], 'r', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 7.0, ['고치기: acc=None으로 두고 if acc is None: acc = []', 'fix: default to acc=None, then if acc is None: acc = []'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['/ 앞은 위치로만, * 뒤(여기선 *args 뒤)는 키워드로만 넘겨요', 'parameters before / are positional-only; those after * (here after *args) are keyword-only'], 'a', 1, { w: 16.0 });
      lbl(S, 'm2', 1, 8.6, ['f(*xs, **opts)처럼 호출할 때 풀어서 넘길 수도 있어요', 'calls can unpack too, as in f(*xs, **opts)'], 'w', 2, { w: 16.0 });
      lbl(S, 'm4', 1, 10.0, ['키워드 전용 인자는 f(x, verbose=True)처럼 호출부를 읽기 쉽게 해요', 'keyword-only parameters make call sites readable, as in f(x, verbose=True)'], 'g', 4, { w: 16.0 });
    },
    notes: [['파라미터는 다섯 종류예요 · / 앞은 위치로만, 그 뒤는 위치나 키워드로, *args는 남는 위치 인자, * 뒤는 키워드로만, **kw는 남는 키워드 인자를 받아요', 'parameters come in five kinds: those before / are positional-only, then positional-or-keyword, *args collects extra positional arguments, those after * are keyword-only, and **kw collects extra keywords'], ['f(1, 5, 6, 7, 8, d=4, e=9)를 부르면 a=1, b=5, c=6이 되고 남는 7, 8은 튜플 args로, d=4는 키워드 전용 d로, 정의되지 않은 e=9는 딕셔너리 kw로 가요', 'calling f(1, 5, 6, 7, 8, d=4, e=9) binds a=1, b=5 and c=6, the leftover 7 and 8 become the tuple args, d=4 fills the keyword-only d, and the undeclared e=9 lands in the dict kw'], ['기본값은 함수를 정의하는 순간 한 번 계산돼 함수 객체에 저장돼요 · 그래서 acc=[]는 모든 호출이 같은 리스트를 써서 add(1), add(2) 뒤 [1, 2]가 돼요', 'default values are evaluated once, when the function is defined, and stored on the function object, so acc=[] is one list shared by every call, giving [1, 2] after add(1) and add(2)'], ['가변 기본값 대신 None을 두고 함수 안에서 새로 만들어요 · 키워드 전용 인자는 호출부를 읽기 쉽게 하고, 위치 전용 인자는 이름을 바꿔도 호출부가 깨지지 않게 해요', 'default to None and create a fresh object inside instead; keyword-only parameters make call sites readable, and positional-only ones let you rename parameters without breaking callers']],
    fin: [['위치 전용 / · *args · 키워드 전용 * · **kwargs', 'positional-only /, *args, keyword-only *, **kwargs', 'pyx-xs pyx-a'], ['기본값은 def 시점에 한 번 평가돼요', 'defaults are evaluated once, at def time'], ['가변 기본값은 None으로 대신해요', 'replace mutable defaults with None']],
    caps: [['파라미터 종류', 'Kinds of parameters'], ['인자 바인딩', 'Binding arguments'], ['기본값 공유', 'Shared defaults'], ['안전한 기본값', 'Safe defaults'], ['인자 규칙', 'Argument rules']]
  });
}

