      lbl(S, 'm1', 1, 7.8, ['"오리처럼 걷고 꽥꽥거리면 오리" · 타입보다 행동을 봐요', '“if it walks and quacks like a duck, it is a duck”: behavior over type'], 'a', 1, { w: 16.0 });
      lbl(S, 'm4', 1, 9.2, ['len()이 리스트, 문자열, 내 클래스 모두에 되는 이유도 __len__이라는 프로토콜', 'len() works on lists, strings and your own classes because __len__ is a protocol'], 'g', 4, { w: 16.0 });
