      lbl(S, 'l2', 19.0, 3.8, ['예외가 나도 __exit__(타입, 값, 트레이스백)가 불려 파일이 닫혀요 · 참을 돌려주면 예외를 삼켜요', 'even on an exception, __exit__(type, value, traceback) runs and closes the file; returning true swallows the exception'], 'r', 2, { w: 12.4 });
