      T(S, 'iwl', X0 + 2.3 * SW, 7.2, ['대기 (네트워크, 디스크)', 'waiting (network, disk)'], 'cz-tc pyx-tiny pyx-g', 2, { w: 6.0 });
      lbl(S, 'l3', 19.0, 8.0, ['CPU 병렬: multiprocessing · GIL을 놓는 C 확장(NumPy) · I/O: 스레드나 asyncio', 'CPU parallelism: multiprocessing or C extensions that release it (NumPy); I/O: threads or asyncio'], 'w', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 9.9, ['GIL 없는 빌드(python3.13t): 3.13 실험, 3.14부터 공식 지원 (PEP 703, 779)', 'the free-threaded build (python3.13t): experimental in 3.13, officially supported from 3.14 (PEP 703, 779)'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['GIL: 한 프로세스에서 한 번에 한 스레드만 바이트코드를 실행하게 하는 락', 'the GIL is a lock letting only one thread per process execute bytecode at a time'], 'a', 1, { w: 16.0 });
      lbl(S, 'm2', 1, 8.4, ['참조 카운트를 락 없이 안전하게 고치려고 생겼어요', 'it exists so reference counts can be updated safely without fine-grained locks'], '', 2, { w: 16.0 });
