      lbl(S, 'm2', 1, 8.4, ['sys.path: 스크립트 폴더, PYTHONPATH, 표준 라이브러리, site-packages', 'sys.path: the script’s folder, PYTHONPATH, the standard library and site-packages'], 'w', 2, { w: 16.0 });
