      lbl(S, 'm4', 1, 9.5, ['너무 넓은 except는 버그를 숨겨요 · 필요한 예외만 잡아요', 'overly broad except clauses hide bugs; catch only what you expect'], 'r', 4, { w: 16.0 });
      lbl(S, 'm4b', 1, 10.9, ['3.11부터 여러 예외를 묶는 ExceptionGroup과 except*', 'since 3.11, ExceptionGroup and except* handle several at once'], '', 4, { w: 16.0 });
